41	import type { EventDetailResponseDTO } from "types/api/event";
42	
43	// Lazy load preview content (only shown in modal when user clicks preview)
44	// Client component, so we can use dynamic directly with ssr: false
45	const PreviewContent = dynamic(
46	  () => import("@components/ui/EventForm/preview/PreviewContent"),
