54	
55	const getDefaultEventDates = () => {
56	  const now = new Date();
57	  now.setMinutes(0, 0, 0);
58	  const startDate = new Date(now);
59	  startDate.setHours(9, 0, 0, 0);
60	  const endDate = new Date(startDate);
61	  endDate.setHours(10, 0, 0, 0);
62	
63	  return {
64	    startDate: startDate.toISOString().slice(0, 16),
65	    endDate: endDate.toISOString().slice(0, 16),
66	  };
67	};
68	
69	const defaultEventDates = getDefaultEventDates();
70	
71	const defaultForm: FormData = {
72	  title: "",
73	  description: "",
74	  type: "FREE",
75	  startDate: defaultEventDates.startDate,
76	  startTime: "",
77	  endDate: defaultEventDates.endDate,
78	  endTime: "",
79	  region: null,
80	  town: null,
81	  location: "",
82	  imageUrl: null,
83	  url: "",
84	  categories: [],
85	  email: "",
86	};
87	
88	const isRegionDTO = (
89	  region: FormData["region"]
90	): region is RegionSummaryResponseDTO =>
91	  Boolean(region && typeof region === "object" && "slug" in region);
92	
93	const isCityDTO = (town: FormData["town"]): town is CitySummaryResponseDTO =>
94	  Boolean(town && typeof town === "object" && "latitude" in town);
95	
96	const isCategoryNamePair = (
97	  category: unknown
98	): category is { id: number; name: string } =>
99	  Boolean(
100	    category &&
101	    typeof category === "object" &&
102	    "id" in category &&
103	    "name" in category
104	  );
105	
106	const isCategoryOption = (
107	  category: unknown
108	): category is { value: string; label: string } =>
109	  Boolean(
110	    category &&
111	    typeof category === "object" &&
112	    "value" in category &&
113	    "label" in category
114	  );
115	
116	const buildFileSignature = (file: File) =>
117	  `${file.name}-${file.size}-${file.lastModified}`;
118	
119	// The form body. Mounted only for authenticated users (see Publica below),
120	// so its data hooks (regions/cities, categories) never fire for guests.
121	const PublishForm = () => {
122	  const t = useTranslations("App.Publish");
123	  const tForm = useTranslations("Components.EventForm");
124	  const router = useRouter();
125	  const [form, setForm] = useState<FormData>(defaultForm);
126	  const [imageFile, setImageFile] = useState<File | null>(null);
127	  const [imagePreview, setImagePreview] = useState<string | null>(null);
128	  const [isPending, startTransition] = useTransition();
129	  const [error, setError] = useState<string | null>(null);
130	  // A submit-time 403 (profileCompleted: false) means the client's session
131	  // state was stale/ambiguous when this form rendered — Publica's own
132	  // top-level gate normally catches this before the form ever mounts. Show
133	  // the same CompleteProfileGate here instead of a generic error, so the
134	  // user has an actual way forward.
135	  const [showCompleteProfileGate, setShowCompleteProfileGate] = useState(false);
136	  const [uploadProgress, setUploadProgress] = useState(0);
137	  const [isUploadingImage, setIsUploadingImage] = useState(false);
138	  const [uploadedImageUrl, setUploadedImageUrl] = useState<string | null>(null);
139	  const [uploadAbortController, setUploadAbortController] =
140	    useState<AbortController | null>(null);
141	  const [uploadedImageSignature, setUploadedImageSignature] = useState<
142	    string | null
143	  >(null);
144	  const [imageUploadMessage, setImageUploadMessage] = useState<string | null>(
145	    null
146	  );
147	
148	  // Funnel tracking refs (no re-render needed)
149	  const formStartedRef = useRef(false);
150	  const fieldsInteractedRef = useRef<Set<string>>(new Set());
151	  const submittedRef = useRef(false);
152	  const abandonFiredRef = useRef(false);
153	
154	  // Track form abandonment on page unload or SPA navigation
155	  useEffect(() => {
156	    const handleBeforeUnload = () => {
157	      if (abandonFiredRef.current) return;
158	      if (formStartedRef.current && !submittedRef.current) {
159	        abandonFiredRef.current = true;
160	        sendGoogleEvent("publish_form_abandon", {
161	          fields_touched: Array.from(fieldsInteractedRef.current).join(","),
162	          fields_count: fieldsInteractedRef.current.size,
163	          source: "publica",
164	        });
165	      }
166	    };
167	    window.addEventListener("beforeunload", handleBeforeUnload);
168	    return () => {
169	      window.removeEventListener("beforeunload", handleBeforeUnload);
170	      // Also fire on SPA navigation (component unmount)
171	      handleBeforeUnload();
172	    };
173	  }, []);
174	
175	  const {
176	    regionsWithCities,
177	    isLoading: isLoadingRegionsWithCities,
178	    isError: isErrorRegionsWithCities,
179	  } = useGetRegionsWithCities();
180	
181	  const isLoadingCities =
182	    isLoadingRegionsWithCities ||
183	    (!regionsWithCities && !isErrorRegionsWithCities);
184	
185	  const { categories } = useCategories();
186	
187	  const { cityOptions, cityToRegionOptionMap } = useMemo(
188	    () => generateCityOptionsWithRegionMap(regionsWithCities),
189	    [regionsWithCities]
190	  );
191	
192	  const categoryOptions = useMemo(
193	    () =>
194	      categories.map((category) => ({
195	        label: category.name,
196	        value: category.id.toString(),
197	      })),
198	    [categories]
199	  );
200	
201	  const trackFieldInteraction = (fieldName: string) => {
202	    if (!formStartedRef.current) {
203	      formStartedRef.current = true;
204	      sendGoogleEvent("publish_form_start", { source: "publica" });
205	    }
206	    if (!fieldsInteractedRef.current.has(fieldName)) {
207	      fieldsInteractedRef.current.add(fieldName);
208	      sendGoogleEvent("publish_field_interact", {
209	        field_name: fieldName,
210	        fields_count: fieldsInteractedRef.current.size,
211	        source: "publica",
212	      });
213	    }
214	  };
215	
216	  const handleFormChange = useCallback(<K extends keyof FormData>(
217	    name: K,
218	    value: FormData[K]
219	  ) => {
220	    trackFieldInteraction(String(name));
221	    setForm((prev) => ({ ...prev, [name]: value }));
222	  }, []);
223	
224	  const handleImageChange = (file: File | null) => {
225	    setError(null);
226	    setImageUploadMessage(null);
227	    trackFieldInteraction("image");
228	
229	    if (!file) {
230	      setImageFile(null);
231	      setImagePreview(null);
232	      setUploadedImageUrl(null);
233	      setUploadedImageSignature(null);
234	      setUploadProgress(0);
235	      return;
236	    }
237	
238	    setImageFile(file);
239	    const reader = new FileReader();
240	    reader.addEventListener("load", () => {
241	      setImagePreview(reader.result as string);
242	    });
243	    reader.readAsDataURL(file);
244	    setUploadedImageUrl(null);
245	    setUploadedImageSignature(null);
246	    setUploadProgress(0);
247	  };
248	
249	  const handleTownChange = (town: Option | null) => {
250	    trackFieldInteraction("town");
251	
252	    setForm((prev) => {
253	      const next = { ...prev, town };
254	      if (town) {
255	        next.region = cityToRegionOptionMap[town.value] ?? null;
256	      } else {
257	        next.region = null;
258	      }
259	      return next;
260	    });
261	  };
262	
263	  const handleCategoriesChange = (categories: Option[]) =>
264	    handleFormChange("categories", categories);
265	
266	  const handleTestUrl = (value: string) => {
267	    const normalized = normalizeUrl(value);
268	    if (!normalized) return;
269	    window.open(normalized, "_blank", "noopener,noreferrer");
270	
271	    sendGoogleEvent("publish_test_url_click", {
272	      ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
273	      source: "publica",
274	    });
275	  };
276	
277	  const [showPreview, setShowPreview] = useState(false);
278	  const [previewEvent, setPreviewEvent] = useState<EventDetailResponseDTO | null>(
279	    null
280	  );
281	
282	  const handlePreview = () => {
283	    sendGoogleEvent("publish_preview_open", {
284	      ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
285	      source: "publica",
286	    });
287	
288	    // Determine the image URL to show in preview
289	    // 1. Uploaded image URL if available
290	    // 2. Currently selected file (as data URL) if available
291	    // 3. Any manual URL entered
292	    const previewImageUrl =
293	      uploadedImageUrl || imagePreview || form.imageUrl || "";
294	
295	    const event = mapDraftToPreviewEvent({
296	      form,
297	      imageUrl: previewImageUrl,
298	    });
299	    setPreviewEvent(event);
300	    setShowPreview(true);
301	  };
302	
303	  const buildE2EExtras = (): E2EEventExtras | undefined => {
304	    const regionIdValue = getRegionValue(form.region);
305	    const townIdValue = getTownValue(form.town);
306	
307	    let regionMeta: RegionSummaryResponseDTO | undefined;
308	    if (regionIdValue) {
309	      if (isRegionDTO(form.region)) {
310	        regionMeta = form.region;
311	      } else if (form.region) {
312	        const option = form.region as Option;
313	        const name = option?.label ?? t("fallbackRegion", { id: regionIdValue });
314	        regionMeta = {
315	          id: Number(regionIdValue),
316	          name,
317	          slug: slugifySegment(name) || `region-${regionIdValue}`,
318	        };
319	      }
320	    }
321	
322	    let cityMeta: CitySummaryResponseDTO | undefined;
323	    if (townIdValue) {
324	      if (isCityDTO(form.town)) {
325	        cityMeta = form.town;
326	      } else if (form.town) {
327	        const option = form.town as Option;
328	        const name = option?.label ?? t("fallbackCity", { id: townIdValue });
329	        cityMeta = {
330	          id: Number(townIdValue),
331	          name,
332	          slug: slugifySegment(name) || `ciutat-${townIdValue}`,
333	          latitude: 41.3851,
334	          longitude: 2.1734,
335	          postalCode: "08001",
336	          rssFeed: null,
337	          enabled: true,
338	        };
339	      }
340	    }
341	
342	    const categoriesMeta =
343	      Array.isArray(form.categories) && form.categories.length > 0
344	        ? form.categories
345	          .map((category, index) => {
346	            if (isCategoryNamePair(category)) {
347	              const slug =
348	                slugifySegment(category.name) || `categoria-${category.id}`;
349	              return {
350	                id: category.id,
351	                name: category.name,
352	                slug,
353	              };
354	            }
355	            if (isCategoryOption(category)) {
356	              const numericId = Number(category.value) || index + 1;
357	              const slug =
358	                slugifySegment(category.label) || `categoria-${numericId}`;
359	              return {
360	                id: numericId,
361	                name: category.label,
362	                slug,
363	              };
364	            }
365	            if (typeof category === "number") {
366	              return {
367	                id: category,
368	                name: `Categoria ${category}`,
369	                slug: `categoria-${category}`,
370	              };
371	            }
372	            return null;
373	          })
374	          .filter(
375	            (
376	              category
377	            ): category is {
378	              id: number;
379	              name: string;
380	              slug: string;
381	            } => Boolean(category)
382	          )
383	        : undefined;
384	
385	    if (!regionMeta && !cityMeta && !categoriesMeta) {
386	      return undefined;
387	    }
388	
389	    return {
390	      region: regionMeta,
391	      city: cityMeta,
392	      province: regionMeta
393	        ? {
394	          id: regionMeta.id,
395	          name: regionMeta.name,
396	          slug: regionMeta.slug,
397	        }
398	        : undefined,
399	      categories: categoriesMeta as CategorySummaryResponseDTO[] | undefined,
400	    };
401	  };
