422	    if (imageFile && imageFile.size > MAX_TOTAL_UPLOAD_BYTES) {
423	      sendGoogleEvent("publish_submit_blocked", {
424	        ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
425	        source: "publica",
426	        reason: "image_too_large_client",
427	      });
428	      setError(
429	        `La imatge supera el límit permès de ${MAX_UPLOAD_LIMIT_LABEL} MB. Si us plau, tria una imatge més petita.`
430	      );
431	      return;
432	    }
433	
434	    if (isUploadingImage) {
435	      sendGoogleEvent("publish_submit_blocked", {
436	        ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
437	        source: "publica",
438	        reason: "upload_in_progress",
439	      });
440	      return;
441	    }
442	
443	    startTransition(async () => {
444	      try {
445	        let resolvedImageUrl =
446	          uploadedImageUrl ||
447	          (form.imageUrl ? normalizeUrl(form.imageUrl) || null : null);
448	
449	        if (imageFile) {
450	          const signature = buildFileSignature(imageFile);
451	          if (signature !== uploadedImageSignature) {
452	            setIsUploadingImage(true);
453	            setUploadProgress(0);
454	            uploadAbortController?.abort();
455	            const controller = new AbortController();
456	            setUploadAbortController(controller);
457	            try {
458	              sendGoogleEvent("publish_image_upload_start", {
459	                ...buildPublishContext({
460	                  form,
461	                  imageFile,
462	                  uploadedImageUrl,
463	                }),
464	                source: "publica",
465	              });
466	
467	              const uploadResult = await uploadImageWithProgress(imageFile, {
468	                onProgress: (percent) => setUploadProgress(percent),
469	                signal: controller.signal,
470	              });
471	              resolvedImageUrl = uploadResult.url;
472	              setUploadedImageUrl(uploadResult.url);
473	              setUploadedImageSignature(signature);
474	              setImageUploadMessage("Imatge pujada correctament.");
475	              setUploadProgress(100);
476	              setTimeout(() => setUploadProgress(0), 800);
477	
478	              sendGoogleEvent("publish_image_upload_success", {
479	                ...buildPublishContext({
480	                  form,
481	                  imageFile,
482	                  uploadedImageUrl: uploadResult.url,
483	                }),
484	                source: "publica",
485	              });
486	            } catch (uploadError) {
487	              const reason = classifyUploadError(uploadError);
488	              if (reason === "abort") {
489	                sendGoogleEvent("publish_image_upload_abort", {
490	                  ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
491	                  source: "publica",
492	                });
493	                setIsUploadingImage(false);
494	                setUploadProgress(0);
495	                setImageUploadMessage(null);
496	                setUploadAbortController(null);
497	                return;
498	              }
499	
500	              sendGoogleEvent("publish_image_upload_error", {
501	                ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
502	                source: "publica",
503	                reason,
504	              });
505	
506	              const uploadMessage =
507	                uploadError instanceof Error
508	                  ? uploadError.message
509	                  : String(uploadError);
510	              if (uploadMessage === EVENT_IMAGE_UPLOAD_TOO_LARGE_ERROR) {
