516	                  "No hem pogut pujar la imatge. Revisa la connexió i torna-ho a intentar."
517	                );
518	              }
519	              setImageUploadMessage(null);
520	              setIsUploadingImage(false);
521	              setUploadProgress(0);
522	              return;
523	            } finally {
524	              setIsUploadingImage(false);
525	              setUploadAbortController(null);
526	            }
527	          }
528	        }
529	
530	        if (!resolvedImageUrl) {
531	          sendGoogleEvent("publish_submit_blocked", {
532	            ...buildPublishContext({ form, imageFile, uploadedImageUrl }),
533	            source: "publica",
534	            reason: "missing_image",
535	          });
536	          setError("La imatge és obligatòria.");
537	          return;
538	        }
539	
540	        const regionLabel =
541	          form.region && "label" in form.region ? form.region.label : "";
542	        const townLabel =
543	          form.town && "label" in form.town ? form.town.label : "";
544	        const location = `${form.location}, ${townLabel}, ${regionLabel}`;
545	
546	        // Normalize URL before sending to backend (auto-add https:// if missing)
547	        const eventData = formDataToBackendDTO({
548	          ...form,
549	          url: normalizeUrl(form.url),
550	          location,
551	          imageUrl: resolvedImageUrl,
552	        });
553	
554	        const e2eExtras = buildE2EExtras();
555	        const result = await createEventAction(eventData, e2eExtras);
556	
557	        if (!result.success) {
558	          sendGoogleEvent("publish_error", {
559	            ...buildPublishContext({
560	              form,
561	              imageFile,
562	              uploadedImageUrl: resolvedImageUrl,
563	            }),
564	            source: "publica",
565	            category:
566	              result.reason === "profile-incomplete"
567	                ? "profile-incomplete"
568	                : "stale-session",
569	          });
570	          if (result.reason === "profile-incomplete") {
