802	              analyticsContext="publica"
803	              isLoading={isPending}
804	              cityOptions={cityOptions}
805	              categoryOptions={categoryOptions}
806	              progress={uploadProgress}
807	              isLoadingCities={isLoadingCities}
808	              handleFormChange={handleFormChange}
809	              handleImageChange={handleImageChange}
810	              handleTownChange={handleTownChange}
811	              handleCategoriesChange={handleCategoriesChange}
812	              imageToUpload={imagePreview}
813	              imageFile={imageFile}
814	              isUploadingImage={isUploadingImage}
815	              uploadMessage={imageUploadMessage}
816	              handleTestUrl={handleTestUrl}
817	              onPreview={handlePreview}
818	              canPreview={true}
819	            />
820	          </div>
821	          <div className="flex-center pt-2 text-center">
822	            <p className="body-small text-foreground/70">
823	              {t("sponsorTitle")}{" "}
824	              <Link
825	                href="/patrocina"
826	                target="_blank"
827	                rel="noopener noreferrer"
828	                className="body-small text-primary hover:text-primary/80 transition-interactive pressable-inline focus-ring"
829	              >
830	                {t("sponsorLink")}
831	              </Link>
832	            </p>
833	          </div>
834	        </div>
835	      </div>
836	    </>
837	  );
838	};
839	
840	/**
841	 * Publishing creates a user-attributed event (the backend returns 401 for
842	 * guests). Gate upfront so guests never fill the form only to fail at submit
843	 * — and, by mounting PublishForm only when authenticated, its region/city
844	 * and category data hooks never fire for guests either. A light skeleton
845	 * holds while the session resolves so an authenticated user never sees the
846	 * gate flash.
847	 */
848	const Publica = () => {
849	  const { isAuthenticated, isLoading, user } = useAuth();
850	
851	  if (isLoading) {
852	    return <AuthCheckSkeleton />;
853	  }
854	
855	  if (!isAuthenticated) {
856	    return <PublishAuthGate />;
857	  }
858	
859	  // Strict `=== false` (not `!user?.profileCompleted`): the field is absent
860	  // during a brief enrichment-failure/loading window, and we'd rather fail
861	  // open than block publishing on ambiguous state — the backend's own 403
862	  // (caught in createEventAction) is the authoritative fallback.
863	  if (user?.profileCompleted === false) {
864	    return <CompleteProfileGate redirectTo="/publica" />;
865	  }
866	
867	  return <PublishForm />;
868	};
869	
870	export default Publica;
